class TraceParityTest {

    // Rule case — followup-basic
    @Test fun ruleFollowupBasic() {
        val rules = TraceRule.parse("contains Redis => followup Redis PING (RESP)")
        assertEquals(1, rules.size)
        assertEquals("redis", rules[0].matchText)
        assertNull(rules[0].matchPort)
        assertEquals(TraceRule.Action.FOLLOWUP, rules[0].action)
        assertEquals("Redis PING (RESP)", rules[0].actionValue)
        assertEquals(true, rules[0].matches(6379, "Redis 7.2".lowercase()))
        assertEquals(false, rules[0].matches(6379, "memcached".lowercase()))
    }

    // Rule case — mixed-block
    @Test fun ruleMixedBlock() {
        val rules = TraceRule.parse("# house rules\n\ncontains nginx => tag web\nport 22 => tag ssh\ncontains openssh => stop\n")
        assertEquals(3, rules.size)
        assertEquals("nginx", rules[0].matchText)
        assertNull(rules[0].matchPort)
        assertEquals(TraceRule.Action.TAG, rules[0].action)
        assertEquals("web", rules[0].actionValue)
        assertEquals(22, rules[1].matchPort)
        assertNull(rules[1].matchText)
        assertEquals(TraceRule.Action.TAG, rules[1].action)
        assertEquals("ssh", rules[1].actionValue)
        assertEquals("openssh", rules[2].matchText)
        assertNull(rules[2].matchPort)
        assertEquals(TraceRule.Action.STOP, rules[2].action)
        assertEquals("", rules[2].actionValue)
        assertEquals(true, rules[0].matches(80, "nginx/1.24".lowercase()))
        assertEquals(false, rules[1].matches(80, "nginx/1.24".lowercase()))
        assertEquals(false, rules[2].matches(80, "nginx/1.24".lowercase()))
        assertEquals(false, rules[0].matches(22, "OpenSSH_9.3".lowercase()))
        assertEquals(true, rules[1].matches(22, "OpenSSH_9.3".lowercase()))
        assertEquals(true, rules[2].matches(22, "OpenSSH_9.3".lowercase()))
        assertEquals(false, rules[0].matches(80, "OpenSSH_9.3".lowercase()))
        assertEquals(false, rules[1].matches(80, "OpenSSH_9.3".lowercase()))
        assertEquals(true, rules[2].matches(80, "OpenSSH_9.3".lowercase()))
    }

