    // Rule case — port-and-contains
    @Test fun rulePortAndContains() {
        val rules = TraceRule.parse("port 6379 => followup Redis PING (RESP)\ncontains redis => tag cache")
        assertEquals(2, rules.size)
        assertEquals(6379, rules[0].matchPort)
        assertNull(rules[0].matchText)
        assertEquals(TraceRule.Action.FOLLOWUP, rules[0].action)
        assertEquals("Redis PING (RESP)", rules[0].actionValue)
        assertEquals("redis", rules[1].matchText)
        assertNull(rules[1].matchPort)
        assertEquals(TraceRule.Action.TAG, rules[1].action)
        assertEquals("cache", rules[1].actionValue)
        assertEquals(true, rules[0].matches(6379, "Redis version 7".lowercase()))
        assertEquals(true, rules[1].matches(6379, "Redis version 7".lowercase()))
        assertEquals(false, rules[0].matches(6380, "Redis".lowercase()))
        assertEquals(true, rules[1].matches(6380, "Redis".lowercase()))
        assertEquals(true, rules[0].matches(6379, "memcached".lowercase()))
        assertEquals(false, rules[1].matches(6379, "memcached".lowercase()))
        assertEquals(false, rules[0].matches(80, "".lowercase()))
        assertEquals(false, rules[1].matches(80, "".lowercase()))
    }

    // Rule case — duplicates-preserved-in-order
    @Test fun ruleDuplicatesPreservedInOrder() {
        val rules = TraceRule.parse("contains a => tag one\ncontains a => tag two")
        assertEquals(2, rules.size)
        assertEquals("a", rules[0].matchText)
        assertNull(rules[0].matchPort)
        assertEquals(TraceRule.Action.TAG, rules[0].action)
        assertEquals("one", rules[0].actionValue)
        assertEquals("a", rules[1].matchText)
        assertNull(rules[1].matchPort)
        assertEquals(TraceRule.Action.TAG, rules[1].action)
        assertEquals("two", rules[1].actionValue)
        assertEquals(true, rules[0].matches(1, "a".lowercase()))
        assertEquals(true, rules[1].matches(1, "a".lowercase()))
        assertEquals(false, rules[0].matches(1, "b".lowercase()))
        assertEquals(false, rules[1].matches(1, "b".lowercase()))
    }

    // Analyze case — http-200-server-title-refs
    @Test fun analyzeHttp200ServerTitleRefs() {
        val a = TraceAnalyzer.analyze("HTTP/1.1 200 OK\r\nServer: nginx/1.24.0\r\nContent-Type: text/html\r\n\r\n<html><head><title>Router Admin</title></head><body>See http://192.168.4.2:8080/ui and 192.168.4.1</body></html>".toByteArray(Charsets.UTF_8), "192.168.4.20", 80)
        assertEquals("45ef56228d4e3a8a32a6b895a2c8e5cf8eca07c254e3ead7091ed774c3c1ca3d", a.signature)
        assertEquals("HTTP/1.1 200 OK", a.firstLine)
        assertEquals("HTTP", a.serviceHint)
        assertEquals(2, a.references.size)
        assertEquals("192.168.4.2", a.references[0].host)
        assertEquals(8080, a.references[0].port)
        assertEquals("192.168.4.1", a.references[1].host)
        assertNull(a.references[1].port)
    }

